$ErrorActionPreference="Stop"
try{$R=Split-Path -Parent $MyInvocation.MyCommand.Path;Set-Location $R;if(!(Test-Path "docs\eight-principles-network")){throw "docs\eight-principles-network not found"};$bk="_backup_eight_principles41_"+(Get-Date -Format "yyyyMMdd-HHmmss");New-Item -ItemType Directory -Force $bk|Out-Null;foreach($s in Get-ChildItem "_payload\docs\eight-principles-network" -File){$d=Join-Path "docs\eight-principles-network" $s.Name;if(Test-Path $d){Copy-Item $d (Join-Path $bk $s.Name) -Force};Copy-Item $s.FullName $d -Force};Write-Host "EIGHT PRINCIPLES MODERNIZATION 41 COMPLETE" -ForegroundColor Green;Write-Host "8 audit-ranked Eight-Principles pages rebuilt in place, not appended." -ForegroundColor Cyan;Write-Host ("Backup: "+$bk) -ForegroundColor Yellow}catch{Write-Host ("ERROR: "+$_.Exception.Message) -ForegroundColor Red};Read-Host "Press Enter to close"